// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.memory.repositoryimport com.roshan.persona.brain.context.SessionIdimport com.roshan.persona.brain.memory.Memoryimport com.roshan.persona.brain.memory.MemoryIdimport com.roshan.persona.brain.memory.MemoryTypeimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport com.roshan.persona.database.dao.EpisodicMemoryDaoimport com.roshan.persona.database.entity.EpisodicMemoryEntityimport timber.log.Timberimport java.time.Instantimport com.roshan.persona.common.AppError/** * NOUS — Episodic Memory Repository. * * Stores and retrieves episodic memories (specific events) via Room. * Each memory has: content, timestamp, importance, tags, embedding. * * Decay: importance decays over time (Ebbinghaus curve). * Tombstone: soft-delete, nightly VACUUM purges tombstoned rows. */class EpisodicMemoryRepository(    private val dao: EpisodicMemoryDao,    /**     * Optional vector engine — when provided, [storeEmbeddingForMemory]     * persists embeddings to the HNSW index + Room for vector search.     */    private val vectorEngine: com.roshan.persona.memory.vector.VectorSearchEngine? = null,) {    suspend fun store(memory: Memory): Result<MemoryId> {        return try {            val now = System.currentTimeMillis()            val entity = EpisodicMemoryEntity(                content = memory.content,                summary = null,                timestamp = memory.timestamp.toEpochMilli(),                importance = memory.importance,                initialImportance = memory.importance,                lastAccessed = now,                lastReinforced = now,                decayConstantDays = 7.0f,                isFlashbulb = memory.importance > 0.9f,                isConsolidated = false,                isDeleted = false,                isHot = true,                emotionalValence = null,                emotionalValencePending = false,                tags = memory.tags.joinToString(","),                correlationId = memory.correlationId?.value,                sessionId = memory.sessionId?.value,                embeddingStatus = "pending",                createdAt = now,                updatedAt = now,            )            val id = dao.insert(entity)            Result.Success(MemoryId(id), CorrelationId.generate(), 0)        } catch (e: Exception) {            Timber.e(e, "Failed to store episodic memory")            Result.Failure(AppError.from(e), CorrelationId.generate(), 0)        }    }    /**     * Store an embedding for a previously-stored memory.     *     * Called by [com.roshan.persona.memory.impl.MemoryInterfaceImpl.store]     * after the memory row is persisted. Delegates to [VectorSearchEngine.storeEmbedding]     * which quantizes to INT8 + updates the HNSW index.     *     * **Previously**: this method did not exist — `storeEmbedding()` on     * `VectorSearchEngine` was never called, so the HNSW index was always     * empty and vector search returned nothing. Audit Task ID: audit-m3-memory P0.     */    suspend fun storeEmbeddingForMemory(memoryId: Long, vector: FloatArray) {        val engine = vectorEngine ?: run {            Timber.tag("EpisodicRepo").w("No VectorSearchEngine wired — embedding not stored for memory $memoryId.")            return        }        try {            engine.storeEmbedding(memoryId, vector)        } catch (t: Throwable) {            Timber.tag("EpisodicRepo").e(t, "storeEmbeddingForMemory failed for memory $memoryId")        }    }    suspend fun getRecent(limit: Int = 50): Result<List<Memory>> {        return try {            val entities = dao.getRecent(limit)            Result.Success(entities.map { it.toMemory() }, CorrelationId.generate(), 0)        } catch (e: Exception) {            Result.Failure(AppError.from(e), CorrelationId.generate(), 0)        }    }    suspend fun recall(query: String, k: Int): Result<List<Memory>> {        return try {            val recent = dao.getRecent(k * 3)            val scored = recent.map { entity ->                val score = computeKeywordScore(entity.content, query)                entity to score            }.sortedByDescending { it.second }.take(k)            Result.Success(scored.map { it.first.toMemory() }, CorrelationId.generate(), 0)        } catch (e: Exception) {            Result.Failure(AppError.from(e), CorrelationId.generate(), 0)        }    }    suspend fun forget(id: MemoryId): Result<Unit> {        return try {            dao.softDelete(id.value)            Result.Success(Unit, CorrelationId.generate(), 0)        } catch (e: Exception) {            Result.Failure(AppError.from(e), CorrelationId.generate(), 0)        }    }    suspend fun forgetAll(): Result<Unit> {        return try {            val all = dao.getRecent(Int.MAX_VALUE)            all.forEach { dao.softDelete(it.id) }            Result.Success(Unit, CorrelationId.generate(), 0)        } catch (e: Exception) {            Result.Failure(AppError.from(e), CorrelationId.generate(), 0)        }    }    suspend fun count(): Int = try { dao.count() } catch (e: Exception) { 0 }    private fun computeKeywordScore(content: String, query: String): Float {        val contentLower = content.lowercase()        val queryTerms = query.lowercase().split(" ").filter { it.length > 2 }        if (queryTerms.isEmpty()) return 0f        var matches = 0        for (term in queryTerms) {            if (contentLower.contains(term)) matches++        }        return matches.toFloat() / queryTerms.size    }}private fun EpisodicMemoryEntity.toMemory(): Memory {    return Memory(        id = MemoryId(this.id),        type = MemoryType.EPISODIC,        content = this.content,        timestamp = Instant.ofEpochMilli(this.timestamp),        importance = this.importance,        tags = if (this.tags.isBlank()) emptySet() else this.tags.split(",").toSet(),        correlationId = this.correlationId?.let { CorrelationId(it) },        sessionId = this.sessionId?.let { SessionId(it) },    )}
